{"description":"Extract unique prompts in first-appearance order","cmd":"cd /app && python3 - <<'EOF'
import re
seen=[]; sset=set()
for l in open('full_prompt_list.txt'):
    m=re.match(r'f(\d+):\s*(.*)',l)
    if not m: continue
    rest=m.group(2)
    prompts=[p.strip() for p in re.findall(r'>\s*([^|]*)',rest) if p.strip()]
    for p in prompts:
        key=p
        if key not in sset:
            sset.add(key); seen.append((int(m.group(1)),p))
for fr,p in seen:
    print(fr,repr(p))
EOF"}
